/*
 * Convert an npm package-lock.json (lockfile v2 or v3) into a yarn v1
 * yarn.lock that records exactly the versions npm resolved. `yarn import`
 * is not used because it re-resolves some entries from the registry.
 */
const DEPENDENCY_FIELDS = ['dependencies', 'optionalDependencies'];
const ROOT_FIELDS = ['dependencies', 'devDependencies', 'optionalDependencies'];
const HEADER =
  '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n' +
  '# yarn lockfile v1\n\n\n';

/** The same quoting rule as yarn's lockfile stringifier. */
function quote(text) {
  const needsQuotes =
    /^(true|false)/.test(text) ||
    /[:\s\\",[\]]/.test(text) ||
    !/^[a-zA-Z]/.test(text);
  return needsQuotes ? JSON.stringify(text) : text;
}

/** The tree path whose node_modules holds `treePath`; '' for the root. */
function parentTree(treePath) {
  const cut = treePath.lastIndexOf('/node_modules/');
  return cut === -1 ? '' : treePath.slice(0, cut);
}

/** Find the tree path Node would load `name` from, starting at `fromPath`. */
function resolvePath(packages, fromPath, name) {
  const candidate = `${fromPath ? `${fromPath}/` : ''}node_modules/${name}`;
  if (packages[candidate]) return candidate;
  if (!fromPath) return null;
  return resolvePath(packages, parentTree(fromPath), name);
}

function requestedDependencies(entry, fields) {
  return fields.flatMap((field) =>
    Object.entries(entry[field] || {}).map(([name, range]) => ({
      name,
      range,
      optional: field === 'optionalDependencies',
    })),
  );
}

/** The tree path npm chose for `dep`; null only when `dep` is optional. */
function locate(packages, fromPath, dep) {
  const found = resolvePath(packages, fromPath, dep.name);
  if (!found && !dep.optional) {
    throw new Error(`${fromPath || 'root'} needs missing ${dep.name}`);
  }
  return found;
}

/** Map every "name@range" that npm resolved to the tree path it chose. */
function collectPatterns(packages) {
  const patterns = new Map();
  Object.entries(packages)
    .filter(([, entry]) => !entry.link && !entry.inBundle)
    .forEach(([fromPath, entry]) => {
      const fields = fromPath === '' ? ROOT_FIELDS : DEPENDENCY_FIELDS;
      requestedDependencies(entry, fields).forEach((dep) => {
        const found = locate(packages, fromPath, dep);
        if (found) patterns.set(`${dep.name}@${dep.range}`, found);
      });
    });
  return patterns;
}

function formatDependencies(entry) {
  return DEPENDENCY_FIELDS.filter((field) => entry[field])
    .map((field) => {
      const lines = Object.keys(entry[field])
        .sort()
        .map((name) => `    ${quote(name)} ${quote(entry[field][name])}`);
      return `  ${field}:\n${lines.join('\n')}\n`;
    })
    .join('');
}

function formatBlock(keys, entry) {
  const integrity = entry.integrity ? `  integrity ${entry.integrity}\n` : '';
  return (
    `${keys.map(quote).join(', ')}:\n` +
    `  version ${quote(entry.version)}\n` +
    `  resolved ${quote(entry.resolved)}\n` +
    integrity +
    formatDependencies(entry)
  );
}

/** Build the text of a yarn.lock from a parsed package-lock.json. */
function yarnLockFromNpm(npmLock) {
  const { packages } = npmLock;
  if (!packages) throw new Error('package-lock.json v2 or later is required');
  // npm may copy one version into several subtrees; yarn lists it once.
  const byTarball = new Map();
  collectPatterns(packages).forEach((treePath, pattern) => {
    const tarball = packages[treePath].resolved || treePath;
    const group = byTarball.get(tarball) || { treePath, keys: [] };
    group.keys.push(pattern);
    byTarball.set(tarball, group);
  });
  const blocks = [...byTarball.values()].map(({ treePath, keys }) => {
    const sortedKeys = keys.sort();
    return { sortedKeys, text: formatBlock(sortedKeys, packages[treePath]) };
  });
  blocks.sort((a, b) => (a.sortedKeys[0] < b.sortedKeys[0] ? -1 : 1));
  return HEADER + blocks.map((block) => block.text).join('\n');
}

module.exports = { yarnLockFromNpm, resolvePath, quote };
